test('invoiceTotals: multiple lines with different discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 10 },
      { qty: 5, unitPrice: 8500, discountPercent: 20 },
      { qty: 2, unitPrice: 8500, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const sub1 = 10 * 8500;
  const sub2 = 5 * 8500;
  const sub3 = 2 * 8500;
  const subtotal = sub1 + sub2 + sub3;
  const discount1 = Math.round(sub1 * 10 / 100);
  const discount2 = Math.round(sub2 * 20 / 100);
  const discount3 = 0;
  const discount = discount1 + discount2 + discount3;
  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, discount);
  assert.strictEqual(totals.total, subtotal - discount);
});

